# Code generated by Claude
"""
Measurement only (David, 2026-10-28, item 3): what the pedestal height does to the arm's clearance, joint margins and reach. Nothing in src/ and no setting is changed.

    MUJOCO_GL=egl python experiments/pedestal_sweep_measure.py RECORD_DIR PEDESTAL_M OUT_JSON [--targets TARGETS_JSON]

RECORD_DIR: an episode directory of experiments/pedestal_episode.py (or demo_video.py --record-only: the 0.10 m episode); its episode/episode_log.csv gives the phases and its
recording/ is replayed (src/replay.py, states verified bit-identical). One MuJoCo process.
 1. Phases: PICK OVER, PICK DOWN, PLACE OVER, PLACE DOWN, from the episode log (10 Hz: a window starts at the first logged row of the phase and ends at the first row of the next one).
 2. At every control tick (every 5th physics step) inside a window: the distance from each elbow (the collision geoms of openarm_<side>_link4, the body of joint 4) to every
    non-robot collision geom (the bench's geoms, the hotplate, the beaker), mj_geomDistance; and each arm joint's margin to its range limit (measured joints). Per window the closest
    approach (mm, which side, which obstacle geom) and the joint margins (rad, deg, closest joint). Also the pad pose at the window's last tick (the waypoint reached).
 3. Reach (from the joint state at the first PICK OVER tick: the base at its stance, the arms at home, this pedestal height): the left arm's IK (MinkArm, the skill's settings, joint limits
    with their margin and collision avoidance, no speed limit) from the home pose, straight pad path, to the pad poses of TARGETS_JSON (the 0.10 m episode's windows: PICK OVER, PICK DOWN,
    PLACE OVER, PLACE DOWN): the pose error at the end. And the maximum downward reach: from the OVER pose lowered in 5 mm steps (each solved to convergence) at the pick's and the place's
    horizontal position until the position error exceeds 2 mm; the lowest pad height reached.
Output: OUT_JSON (written to a temporary file, then renamed).
"""
import argparse
import csv
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
os.environ.setdefault("MUJOCO_GL", "egl")

import mink  # noqa: E402
import mujoco  # noqa: E402
import numpy as np  # noqa: E402
from scipy.spatial.transform import Rotation, Slerp  # noqa: E402

import src.replay as replay_mod  # noqa: E402
from src.gripper_geometry import gripper_frame  # noqa: E402
from src.mink_arm import MinkArm  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402

PHASES = ("PICK: OVER", "PICK: DOWN", "PLACE: OVER", "PLACE: DOWN", "PICK: IN")      # the first four are the extended phases of the request; PICK: IN is measured to see why a height fails there
REACH_PHASES = PHASES[:4]
REACH_TOL_M = 0.002          # m: the lowest pad height counts as reached while the position error is below this


def windows_from_log(path):
    rows = list(csv.reader(open(path)))[1:]
    out = {}
    for i, r in enumerate(rows):
        for ph in PHASES:
            if ph in r[1] and ph not in out:
                end = next((float(rr[0]) for rr in rows[i + 1:] if ph not in rr[1]), float(rows[-1][0]))
                out[ph] = (float(r[0]), end)
    return out


def replay_measure(rec_dir, windows):
    ctx, per, snap, ends = {}, {ph: {"dist": [], "margin": []} for ph in windows}, {}, {}

    def hook(step_count, data):
        m = MODEL[0]
        if not ctx:
            gf = gripper_frame(m, "left")
            col = [g for g in range(m.ngeom) if (m.geom_contype[g] or m.geom_conaffinity[g])]
            bname = lambda g: m.body(int(m.geom_bodyid[g])).name
            robot_bodies = set()
            root = m.body("base_link").id
            for b in range(m.nbody):
                x = b
                while x != 0 and x != root:
                    x = int(m.body_parentid[x])
                if x == root:
                    robot_bodies.add(b)
            ctx.update(
                tcp=m.body("openarm_left_hand_tcp").id, pad=np.asarray(gf["pad_center_in_tcp"], float),
                Rp=np.column_stack([gf["closing_axis"], np.cross(gf["approach_axis"], gf["closing_axis"]), gf["approach_axis"]]),
                elbow={s: [g for g in col if bname(g) == f"openarm_{s}_link4"] for s in ("left", "right")},
                obst=[g for g in col if int(m.geom_bodyid[g]) not in robot_bodies and int(m.geom_bodyid[g]) != 0],
                arm_geoms=[g for g in col if bname(g).startswith("openarm_left_") and not bname(g).endswith(("link0", "link1", "link2"))],
                furniture=[g for g in col if bname(g) in ("bench", "task_hotplate")],
                ids={s: arm_ids(m, s) for s in ("left", "right")},
                ranges={s: m.jnt_range[arm_ids(m, s)["jnt"]] for s in ("left", "right")})
        if int(round(data.time * 750)) % 5:
            return
        for ph, (t0, t1) in windows.items():
            if not (t0 <= data.time <= t1):
                continue
            if "qpos" not in snap:
                snap["qpos"], snap["t"] = data.qpos.copy(), float(data.time)
            best = (1e9, None, None, None)
            for s, gs in ctx["elbow"].items():
                for g in gs:
                    for o in ctx["obst"]:
                        dist = mujoco.mj_geomDistance(m, data, g, o, 1.0, None)
                        if dist < best[0]:
                            best = (dist, s, m.geom(g).name or f"geom{g}", f"{m.body(int(m.geom_bodyid[o])).name}/{m.geom(o).name or 'geom' + str(o)}")
            per[ph]["dist"].append((float(data.time), *best))
            af = (1e9, None, None)
            for g in ctx["arm_geoms"]:
                for o in ctx["furniture"]:
                    dist = mujoco.mj_geomDistance(m, data, g, o, 1.0, None)
                    if dist < af[0]:
                        af = (dist, m.geom(g).name or f"geom{g}", m.geom(o).name or f"geom{o}")
            per[ph].setdefault("armfurn", []).append((float(data.time), *af))
            mg = {}
            for s in ("left", "right"):
                q = data.qpos[ctx["ids"][s]["qadr"]]
                r = ctx["ranges"][s]
                mg[s] = np.minimum(q - r[:, 0], r[:, 1] - q)
            per[ph]["margin"].append((float(data.time), mg["left"].copy(), mg["right"].copy()))
            R = data.xmat[ctx["tcp"]].reshape(3, 3)
            if ph in REACH_PHASES:
                pass
            ends[ph] = (data.xpos[ctx["tcp"]] + R @ ctx["pad"], R @ ctx["Rp"])

    MODEL = [None]
    orig = replay_mod.run_loop

    def spy(model, data, sources, cfg, viewer=None):
        MODEL[0] = model
        return orig(model, data, sources, cfg, viewer=viewer)

    replay_mod.run_loop = spy
    r = replay_mod.replay_run(Path(rec_dir) / "recording", out_dir=Path(os.environ.get("TMPDIR", "/tmp")) / "replay_ped_tmp", video="none", verify=True, quiet=True, step_hook=hook)
    replay_mod.run_loop = orig
    print(f"replay ok {r['ok']} ticks {r['ticks']} mismatch {r['mismatch']}", flush=True)
    return MODEL[0], per, snap, ends, ctx, r


def summarize(per, ctx, model):
    out = {}
    for ph, d in per.items():
        if not d["dist"]:
            continue
        dd = min(d["dist"], key=lambda x: x[1])
        res = {"closest_elbow_mm": 1000 * dd[1], "side": dd[2], "elbow_geom": dd[3], "obstacle": dd[4], "at_s": dd[0], "ticks": len(d["dist"])}
        for side, k in (("left", 1), ("right", 2)):
            mg = np.array([x[k] for x in d["margin"]])
            mn = mg.min(axis=0)
            j = int(mn.argmin())
            res[f"{side}_joint_margin"] = {"closest_joint": j + 1, "margin_rad": float(mn[j]), "margin_deg": float(math.degrees(mn[j])), "per_joint_min_deg": [float(math.degrees(v)) for v in mn]}
        last = d["dist"][-1]
        res["at_window_end"] = {"elbow_mm": 1000 * last[1], "elbow_obstacle": last[4],
                                "left_joint_margin_deg": [float(math.degrees(v)) for v in d["margin"][-1][1]],
                                "right_joint_margin_deg": [float(math.degrees(v)) for v in d["margin"][-1][2]]}
        af = d["armfurn"]
        mn = min(af, key=lambda x: x[1])
        res["left_arm_to_furniture_min_mm"] = {"mm": 1000 * mn[1], "arm_geom": mn[2], "furniture_geom": mn[3], "at_s": mn[0], "at_window_end_mm": 1000 * af[-1][1], "solver_min_distance_mm": 8.0}
        out[ph] = res
    return out


def reach(model, snap, targets):
    d = mujoco.MjData(model)
    d.qpos[:] = snap["qpos"]
    mujoco.mj_forward(model, d)
    home = np.asarray(TASK_CFG["home_q_left"], float)
    arm = MinkArm(model, d, "left", home)
    arm.reset(d)
    p_home, R_home = arm.pad_pose(d)
    frame = mink.FrameTask("openarm_left_hand_tcp", "body", position_cost=arm.cfg["position_cost"], orientation_cost=arm.cfg["orientation_cost"])

    LIM = {"all": arm.pose_limits, "joints_only": [arm.pose_limits[0]]}      # the solver's limits (joint range with its 10 deg margin and collision avoidance), or the joint range only

    def solve(config, p, R, iters=300, tol=1e-4, limits=None):
        R_tcp = np.asarray(R, float) @ arm.R_pad_in_tcp.T
        frame.set_target(mink.SE3.from_rotation_and_translation(mink.SO3.from_matrix(R_tcp), np.asarray(p, float) - R_tcp @ arm.pad_in_tcp))
        for _ in range(iters):
            if float(np.linalg.norm(frame.compute_error(config))) < tol:
                break
            v = mink.solve_ik(config, [frame, arm.posture], 0.05, arm.cfg["solver"], damping=arm.cfg["damping"], limits=limits or arm.pose_limits, constraints=[arm.freeze])
            config.integrate_inplace(v, 0.05)

    def pad_of(config):
        d2 = mujoco.MjData(model)
        d2.qpos[:] = config.q
        mujoco.mj_kinematics(model, d2)
        return arm.pad_pose(d2)

    def err(config, p, R):
        pp, RR = pad_of(config)
        return float(np.linalg.norm(pp - p)), float(math.degrees(np.linalg.norm(Rotation.from_matrix(RR.T @ R).as_rotvec())))

    def new_config():
        q = d.qpos.copy()
        q[arm.qadr] = home
        return mink.Configuration(model, q=q)

    out = {"home_pad": p_home.tolist(), "targets": {}, "max_down": {}}
    targets = {k: v for k, v in targets.items() if k in REACH_PHASES}
    for ph, (p, R) in targets.items():
        p, R = np.asarray(p, float), np.asarray(R, float)
        cfg = new_config()
        sl = Slerp([0.0, 1.0], Rotation.from_matrix([R_home, R]))
        status = "ok"
        try:
            for u in np.linspace(0.0, 1.0, 31):
                solve(cfg, p_home + (p - p_home) * u, sl(u).as_matrix())
        except mink.NoSolutionFound as e:
            status = f"no solution: {e}"
        e_mm, e_deg = err(cfg, p, R)
        out["targets"][ph] = {"target": p.tolist(), "pos_error_mm": 1000 * e_mm, "rot_error_deg": e_deg, "status": status, "q_left_deg": [float(math.degrees(v)) for v in cfg.q[arm.qadr]]}
        cfg = new_config()                                       # the same path with the joint range only (no collision avoidance, no margin)
        try:
            for u in np.linspace(0.0, 1.0, 31):
                solve(cfg, p_home + (p - p_home) * u, sl(u).as_matrix(), limits=LIM["joints_only"])
        except mink.NoSolutionFound:
            pass
        out["targets"][ph]["pos_error_mm_joint_range_only"] = 1000 * err(cfg, p, R)[0]
    for mode in ("all", "joints_only"):
        lim = LIM[mode]
        for name, (over, down) in {"pick": ("PICK: OVER", "PICK: DOWN"), "place": ("PLACE: OVER", "PLACE: DOWN")}.items():
            if over not in targets or down not in targets:
                continue
            po, Ro = (np.asarray(x, float) for x in targets[over])
            pd, Rd = (np.asarray(x, float) for x in targets[down])
            cfg = new_config()
            sl = Slerp([0.0, 1.0], Rotation.from_matrix([R_home, Ro]))
            try:
                for u in np.linspace(0.0, 1.0, 31):
                    solve(cfg, p_home + (po - p_home) * u, sl(u).as_matrix(), limits=lim)
            except mink.NoSolutionFound:
                pass
            e0, _ = err(cfg, po, Ro)
            lowest, z = None, float(po[2])
            stop = "reached 100 mm below the waypoint"
            if e0 > REACH_TOL_M:
                stop = f"the OVER pose itself is {1000 * e0:.1f} mm short"
            else:
                lowest = z
                while z > pd[2] - 0.10:
                    z -= 0.005
                    tgt = np.array([pd[0], pd[1], z])
                    try:
                        solve(cfg, tgt, Rd, limits=lim)
                    except mink.NoSolutionFound:
                        stop = "no solution"
                        break
                    e, _ = err(cfg, tgt, Rd)
                    if e > REACH_TOL_M:
                        stop = f"error {1000 * e:.1f} mm at z={z:.3f}"
                        break
                    lowest = z
                    last_q = cfg.q[arm.qadr].copy()
            out["max_down"][f"{name}_{mode}"] = {"xy": [float(pd[0]), float(pd[1])], "needed_pad_z": float(pd[2]), "lowest_pad_z_reached": lowest,
                                                  "lowest_minus_needed_mm": None if lowest is None else 1000 * (lowest - pd[2]), "stop": stop}
    return out


def main(a):
    windows = windows_from_log(Path(a.record_dir) / "episode" / "episode_log.csv")
    summary = json.load(open(Path(a.record_dir) / "episode" / "episode_summary.json"))
    out = {"record_dir": str(a.record_dir), "pedestal_m": a.pedestal_m, "outcome": summary.get("outcome"), "windows": {k: list(v) for k, v in windows.items()}}
    for k in ("failure", "plan_failure", "reason", "message", "status"):
        if k in summary:
            out[f"summary_{k}"] = summary[k]
    if not windows:
        print("no PICK/PLACE phase reached; nothing to measure")
    else:
        model, per, snap, ends, ctx, rep = replay_measure(a.record_dir, windows)
        out["replay_ok"] = bool(rep["ok"])
        out["phases"] = summarize(per, ctx, model)
        out["pad_at_window_end"] = {ph: (p.tolist(), R.tolist()) for ph, (p, R) in ends.items()}
        tf = json.load(open(a.targets)) if a.targets else out["pad_at_window_end"]
        tf = tf.get("pad_at_window_end", tf)
        targets = {ph: (np.array(v[0]), np.array(v[1])) for ph, v in tf.items()}
        if "qpos" in snap:
            out["reach"] = reach(model, snap, targets)
    tmp = Path(a.out + ".tmp")
    tmp.write_text(json.dumps(out, indent=1))
    os.replace(tmp, a.out)
    print(json.dumps({k: v for k, v in out.items() if k != "pad_at_window_end"}, indent=1)[:7000])
    return 0


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("record_dir")
    ap.add_argument("pedestal_m", type=float)
    ap.add_argument("out")
    ap.add_argument("--targets")
    sys.exit(main(ap.parse_args()))
